parameters.jsCode:
const body = $input.first().json.body || {};
const options = body.data?.options || [];

const description = options.find(o => o.name === 'description')?.value || 'No detailed description provided.';
const logs = options.find(o => o.name === 'logs')?.value || 'No telemetry logs attached.';
const severity = options.find(o => o.name === 'severity')?.value || 'medium';
const username = body.member?.user?.username || body.user?.username || 'unknown_agent';
const userId = body.member?.user?.id || body.user?.id || '000000000000000000';
const timestamp = new Date().toISOString();

return {
  description,
  logs,
  severity,
  username,
  userId,
  timestamp
};

